public class Wallet {
    // 金额以"分"为单位存 int，乘法溢出
    public int applyFee(int amountCents, int feeBps) {
        // feeBps 为基点（万分之），amountCents * feeBps 可能溢出
        int fee = (amountCents * feeBps) / 10000;
        return amountCents - fee;
    }
}

